DROP TABLE IF EXISTS `sys_number_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_number_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `rule_code` varchar(64) NOT NULL COMMENT '规则编码,如 EXP_CLAIM',
  `rule_name` varchar(100) NOT NULL COMMENT '规则名称',
  `prefix` varchar(20) DEFAULT '' COMMENT '前缀,如 BX',
  `date_format` varchar(20) DEFAULT 'yyyyMMdd' COMMENT '日期格式,为空表示不含日期',
  `seq_length` int NOT NULL DEFAULT '4' COMMENT '流水号位数',
  `reset_cycle` varchar(20) NOT NULL DEFAULT 'DAY' COMMENT '流水重置周期:NONE不重置/DAY按日/MONTH按月/YEAR按年',
  `step` int NOT NULL DEFAULT '1' COMMENT '步长',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL/DISABLED',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_rule_code` (`tenant_id`,`rule_code`),
  KEY `idx_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='单据编号规则';
/*!40101 SET character_set_client = @saved_cs_client */;

